def transform(grid):
    h, w = len(grid), len(grid[0])
    cr = next(r for r in range(h) if all(grid[r][c] == 3 for c in range(w)))
    cc = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))

    # Pattern indexed by distance from the two 3-lines.
    near = {
        1: [0, 4, 0, 4, 0, 4],
        2: [4, 4, 0, 4, 0, 4],
        3: [0, 0, 0, 4, 0, 4],
        4: [4, 4, 4, 4, 0, 4],
    }

    out = []
    for r in range(h):
        row = []
        dr = abs(r - cr)
        for c in range(w):
            dc = abs(c - cc)
            if r == cr or c == cc:
                row.append(3)
            elif dr in near and 1 <= dc <= 6:
                row.append(near[dr][dc - 1])
            elif dr == 5:
                row.append(4 if dc == 6 else 0)
            elif dr >= 6:
                row.append(4 if dr % 2 == 0 else 0)
            else:
                row.append(0)
        out.append(row)
    return out
